// Rotar entre blogs usando el minuto actual como índice
const minutoActual = new Date().getMinutes();
const idx = minutoActual % BLOGS_TABS.length;
const blog = BLOGS_TABS[idx];

return [{ json: { blog, SHEETS_ID: '14NYqDn77J9nsTjD8ZsvxzDe1lggNwmC6kUZcE3LNbJI' } }];

const tema = $input.item.json;
const config = $('Seleccionar Blog a Procesar').item.json;
const { blog } = config;

if (!tema || !tema.titulo) {
  return [{ json: { skip: true, motivo: 'No hay temas pendientes para ' + blog.nombre } }];
}

return [{ json: { tema, blog, skip: false } }];

const resp1 = $input.item.json;
const ctx = $('Verificar Tema Disponible').item.json;

let rawContent = resp1.choices?.[0]?.message?.content || '{}';
rawContent = rawContent.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();

let estructura;
try { estructura = JSON.parse(rawContent); } catch(e) {
  const match = rawContent.match(/\{.*\}/s);
  estructura = match ? JSON.parse(match[0]) : {};
}

return [{ json: { ...ctx, estructura } }];

const respContenido = $input.item.json;
const ctx = $('Parsear Estructura').item.json;
const { tema, blog, estructura } = ctx;

const contenidoIA = respContenido.choices?.[0]?.message?.content || '';

// -------------------------------------------------------
// PRODUCTOS HOTMART
// -------------------------------------------------------
const PRODUCTOS = {
  'dieta-natural':   { nombre:'Dieta Natural para Perros y Gatos',  link:'https://go.hotmart.com/X103617747C',      img:'https://static-media.hotmart.com/KNdDfZogqE2CWDv4nqEsswzDFjc=/300x300/filters:quality(100)/hotmart/product_pictures/ecbf6914-08bb-4682-aa5b-1990b80b5afb/postinstagrampatitas.png',  grad:'135deg,#1a7a4a,#2ecc71', text:'#1a7a4a', tipo:'Guía' },
  'snack-barf':      { nombre:'Snack BARF en Minutos',              link:'https://go.hotmart.com/R103617833Q',      img:'https://static-media.hotmart.com/XusqQYSq_oAB8-EO0Iwr3xVnPMk=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/aaef333c-c030-4c46-a0e7-0c1b780837fe/snackbarf600x600.png?w=920', grad:'135deg,#1a7a4a,#27ae60', text:'#1a7a4a', tipo:'Recetas' },
  'adiestramiento':  { nombre:'Adiestramiento Canino Profesional',  link:'https://go.hotmart.com/D104257979A',      img:'https://hotmart.s3.amazonaws.com/product_pictures/141a3c3d-a535-40f5-99e1-a275199b7e98/Portadahotmart5.png',  grad:'135deg,#1a5276,#2980b9', text:'#1a5276', tipo:'Curso' },
