  'mascotas-sanas':  { nombre:'Mascotas Sanas',                     link:'https://go.hotmart.com/L104257678P?dp=1', img:'https://static-media.hotmart.com/9H3NJb3S4H61OsufTjZpXLy-8KY=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/78592f13-96f1-4724-9b6a-2640aadcf606/MasterSello20211116T162945331.jpg?w=920', grad:'135deg,#1a5276,#2980b9', text:'#1a5276', tipo:'Curso' },
  'vital-pet':       { nombre:'Vital Pet System',                   link:'https://go.hotmart.com/W104257847B',      img:'https://static-media.hotmart.com/F3PzytJIAVCectZMFSnvMHJFV5g=/filters:background_color(white)/hotmart/product_pictures/a801721c-590d-4a30-ab01-5fe5eb532e8f/PORTADAVITALPET.png', grad:'135deg,#1a7a4a,#27ae60', text:'#1a7a4a', tipo:'Sistema' },
  'calculadora':     { nombre:'Calculadora de Alimentación Cocida', link:'https://go.hotmart.com/B104226750N',      img:'https://static-media.hotmart.com/Gt9GpGBSzCdG8hfSbvKgGuXEhFY=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/5f151330-675e-4498-8764-1fba21c4b505/Calculadoradealimentacioncocidaparaperrosygatos.png?w=920', grad:'135deg,#1a7a4a,#27ae60', text:'#1a7a4a', tipo:'Herramienta' },
  '101-recetas-diabeticos': { nombre:'101 Recetas Saludables para Diabéticos', link:'https://go.hotmart.com/S104258050O', img:'https://static-media.hotmart.com/EbTb3aQIURTRGGIiuAGCZrrR6sk=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/48ca379d-a33d-4e0d-bea7-d8d375784e2d/_dca15be1487946e9bbd84e59e20a9d46.jpg?w=920', grad:'135deg,#c0392b,#e74c3c', text:'#c0392b', tipo:'Recetario' }
};

const ADSENSE_ID = 'ca-pub-1913674678143092';

// Seleccionar producto
const prodId = tema.producto_relacionado || estructura.producto_sugerido || 'mascotas-sanas';
const prod = PRODUCTOS[prodId] || PRODUCTOS['mascotas-sanas'];

// AdSense mid-article
const adsenseMid = `
<div style="margin:32px 0;text-align:center">
  <ins class="adsbygoogle" style="display:block" data-ad-client="${ADSENSE_ID}" data-ad-slot="SLOT_MID" data-ad-format="auto" data-full-width-responsive="true"></ins>
  <script>(adsbygoogle = window.adsbygoogle || []).push({});</script>
</div>`;

// Insertar AdSense a mitad del contenido
const mitad = Math.floor(contenidoIA.length / 2);
const corte = contenidoIA.indexOf('</p>', mitad);
const punto = corte > 0 ? corte + 4 : mitad;
const contenidoConAds = contenidoIA.slice(0, punto) + adsenseMid + contenidoIA.slice(punto);

// Banner Hotmart (para blogs de animales/salud)
let bannerMonetizacion = '';
if (blog.nicho === 'animales' || blog.nicho === 'salud') {
  bannerMonetizacion = `
<!-- HOTMART:${prodId} -->
<div style="background:linear-gradient(${prod.grad});border-radius:14px;padding:0;margin:40px 0;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.12);font-family:Arial,sans-serif;max-width:700px">
  <div style="display:flex;align-items:stretch;flex-wrap:wrap">
    <img src="${prod.img}" alt="${prod.nombre}" loading="lazy" style="width:150px;height:auto;object-fit:cover;flex-shrink:0">
    <div style="flex:1;min-width:180px;padding:20px;display:flex;flex-direction:column;justify-content:center">
      <p style="color:rgba(255,255,255,.8);font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin:0 0 5px">${prod.tipo} recomendado</p>
      <h3 style="color:#fff;font-size:17px;font-weight:800;margin:0 0 8px;line-height:1.3">${prod.nombre}</h3>
      <a href="${prod.link}" target="_blank" rel="noopener sponsored" style="display:inline-block;background:#fff;color:${prod.text};font-weight:800;font-size:13px;padding:10px 20px;border-radius:8px;text-decoration:none;align-self:flex-start">Ver ahora →</a>
    </div>
  </div>
  <p style="color:rgba(255,255,255,.3);font-size:9px;text-align:right;padding:3px 12px;margin:0">*Enlace de afiliado</p>
</div>`;
} else if (blog.nicho === 'leyes') {
  bannerMonetizacion = `
<!-- LEAD WIDGET -->
<div style="background:linear-gradient(135deg,#1a2a6c,#2d5fa6);border-radius:14px;padding:24px 28px;margin:40px 0;font-family:Arial,sans-serif;box-shadow:0 4px 16px rgba(0,0,0,.15);max-width:700px">
  <div style="display:flex;align-items:center;gap:16px;flex-wrap:wrap">
    <div style="font-size:44px;flex-shrink:0">⚖️</div>
    <div style="flex:1;min-width:200px">
      <p style="color:rgba(255,255,255,.8);font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin:0 0 4px">Consulta GRATUITA</p>
      <h3 style="color:#fff;font-size:19px;font-weight:800;margin:0 0 6px;line-height:1.3">${blog.nombre}</h3>
      <p style="color:rgba(255,255,255,.85);font-size:13px;margin:0">Sin costo. Confidencial. Respuesta en 24h.</p>
    </div>
    <div style="display:flex;flex-direction:column;gap:8px;flex-shrink:0">
      <a href="tel:+18000000000" style="display:inline-block;background:#fff;color:#1a2a6c;font-weight:800;font-size:14px;padding:12px 22px;border-radius:8px;text-decoration:none;text-align:center">📞 Llamar Gratis</a>
      <a href="https://wa.me/18000000000" target="_blank" rel="noopener" style="display:inline-block;background:#25d366;color:#fff;font-weight:800;font-size:13px;padding:10px 22px;border-radius:8px;text-decoration:none;text-align:center">💬 WhatsApp</a>
    </div>
  </div>
</div>`;
}

// AdSense bottom
const adsenseBottom = `
<div style="margin:32px 0;text-align:center">
  <ins class="adsbygoogle" style="display:block" data-ad-client="${ADSENSE_ID}" data-ad-slot="SLOT_BOTTOM" data-ad-format="auto" data-full-width-responsive="true"></ins>
  <script>(adsbygoogle = window.adsbygoogle || []).push({});</script>
</div>`;

const htmlFinal = contenidoConAds + bannerMonetizacion + adsenseBottom;

return [{
  json: {
    blogId: blog.blogId,
    blogNombre: blog.nombre,
    blogNicho: blog.nicho,
    blogTab: blog.tab,
    titulo: estructura.titulo_final || tema.titulo,
    keyword: tema.keyword,
    labels: [blog.nicho, tema.formato || 'guia'].filter(Boolean),
    contenido: htmlFinal,
    fecha_publicacion: tema.fecha_publicacion,
    num_articulo: tema.num_articulo,
    row_number: tema.row_number
  }
}];

// No hay temas pendientes — registrar y terminar
const blog = $('Seleccionar Blog a Procesar').item.json.blog;
console.log(`ℹ️ Sin temas pendientes para blog: ${blog.nombre}`);
return [{ json: { status: 'sin_temas', blog: blog.nombre } }];
